local({
  value <- recode_values(
    coalesce(as.numeric(BB083), as.numeric(SEX), as.numeric(SEXCOMP)),
    1 ~ "Male",
    2 ~ "Female",
    default = NA_character_
  )
  coalesce(modal_within(value, ID), "Unknown")
})

local({
  score <- case_when(
    wave == "Base year 1980" & as.numeric(BBSESRAW) < 98 ~ as.numeric(BBSESRAW),
    wave == "First follow-up 1982" & as.numeric(FUSES) < 98 ~ as.numeric(FUSES),
    .default = NA_real_
  )
  low <- stats::ave(score, wave, FUN = function(v) stats::quantile(v, 0.4, na.rm = TRUE, names = FALSE))
  high <- stats::ave(score, wave, FUN = function(v) stats::quantile(v, 0.6, na.rm = TRUE, names = FALSE))
  case_when(is.na(score) ~ "Unknown", score <= low ~ "Low", score > high ~ "High", .default = "Medium")
})

local({
  bands <- cbind(as.numeric(BB096A), as.numeric(BB096B), as.numeric(BB096C), as.numeric(BB096D), as.numeric(BB096E))
  bands[!(bands %in% 1:6)] <- NA
  count82 <- coalesce(if_else(as.numeric(FUSTTYPE) %in% 2, as.numeric(FD54), as.numeric(FY106)), as.numeric(FE70))
  case_when(
    wave == "Base year 1980" ~ rowSums(bands - 1),
    wave == "First follow-up 1982" ~ if_else(count82 %in% 1:7, count82 - 1, NA_real_),
    .default = NA_real_
  )
})

local({
  items <- cbind(
    coalesce(as.numeric(BB046A), as.numeric(FY57A)),
    coalesce(as.numeric(BB046B), as.numeric(FY57B)),
    coalesce(as.numeric(BB046C), as.numeric(FY57C))
  )
  items[!(items %in% 1:2)] <- NA
  rowMeans(2 - items)
})

local({
  sector <- recode_values(as.numeric(SCHSAMP), 0:3 ~ "Public", 5:9 ~ "Private", default = "Unknown")
  case_when(
    wave == "Base year 1980" ~ sector,
    wave == "First follow-up 1982" & as.numeric(FUSTTYPE) == 1 ~ sector,
    .default = "Unknown"
  )
})

local({
