})

local({
  score <- case_when(
    wave == "Base year 1980" ~ as.numeric(YBSCINSD),
    wave == "First follow-up 1982" & as.numeric(cohort) == 1 ~ as.numeric(FYSCINSD),
    .default = NA_real_
  )
  if_else(score > 0 & score < 900, score, NA_real_)
})

local({
  items <- cbind(
    coalesce(as.numeric(YB016A), as.numeric(FY18A)),
    coalesce(as.numeric(YB016B), as.numeric(FY18B)),
    coalesce(as.numeric(YB016C), as.numeric(FY18C))
  )
  items[!(items %in% 1:4)] <- NA
  score <- rowMeans(items)
  if_else(wave == "First follow-up 1982" & !(as.numeric(FUSTTYPE) %in% c(1, 3)), NA_real_, score)
})

